export default {
  version: 1,
  name: "Grounded Spring",
  description: "While grounded, the courier has friction 0.9, bounce 0.45, and a brass glow. While airborne, friction returns to 0.82, bounce to 0, and the glow disappears.",
  rules: [
    {
      id: "grounded-spring",
      each: "player",
      when: { compare: { left: { field: "grounded" }, op: "eq", right: 1 } },
      actions: [
        { type: "material", target: "self", friction: 0.9, bounce: 0.45 },
        { type: "cue", target: "self", color: "brass", intensity: 1 }
      ]
    },
    {
      id: "airborne-baseline",
      each: "player",
      when: { compare: { left: { field: "grounded" }, op: "eq", right: 0 } },
      actions: [
        { type: "material", target: "self", friction: 0.82, bounce: 0 },
        { type: "cue", target: "self", color: "brass", intensity: 0 }
      ]
    }
  ]
} satisfies RuleModule;
